# Replay every transaction from the per-identity endowment; unconfirmed
# (pending tip) transactions are included so a candidate can never hide
# an overspend behind a pending final block. The same pass enforces the
# per-sender sequenced-transfer nonce stream from genesis: a sequenced
# nonce must be exactly the sender's next expected value, so a gap, a
# duplicate/conflicting nonce or a non-zero first nonce rejects the
# chain. Legacy (nonce-less) transactions are outside the stream.
balances: dict[str, int] = {}
next_nonces: dict[str, int] = {}
for block in blocks:
    for tx in block.transactions:
        sender_balance = balances.get(tx.sender, endowment)
        if sender_balance < tx.amount:
            raise ValueError(
                f"replay overspend by {tx.sender} in block {block.height}"
            )
        balances[tx.sender] = sender_balance - tx.amount
        balances[tx.recipient] = balances.get(tx.recipient, endowment) + tx.amount
        if tx.nonce is not None:
            expected_nonce = next_nonces.get(tx.sender, 0)
            if tx.nonce < expected_nonce:
                raise ValueError(
                    f"sequenced nonce {tx.nonce} for sender {tx.sender} "
                    f"in block {block.height} repeats an already-used nonce"
                )
            if tx.nonce > expected_nonce:
                raise ValueError(
                    f"sequenced nonce {tx.nonce} for sender {tx.sender} "
                    f"in block {block.height} skips nonce {expected_nonce}"
                )
            next_nonces[tx.sender] = expected_nonce + 1
return blocks

