# Replay every transaction from the per-identity endowment; unconfirmed
# (pending tip) transactions are included so a candidate can never hide
# an overspend behind a pending final block. The same pass enforces the
# per-sender sequenced-transfer nonce stream from genesis: transactions
# are stored ascending by tx_id inside each block, so one sender's
# sequenced nonces may appear in any within-block order; across block
# heights, however, each block's per-sender nonce set must be exactly
# the next dense run {expected, ..., expected+k-1}. A gap, a duplicate
# nonce, a conflicting same-nonce transaction or a non-zero first nonce
# rejects the chain. Legacy (nonce-less) transactions are outside the
# stream.
balances: dict[str, int] = {}
next_nonces: dict[str, int] = {}
for block in blocks:
    block_nonces: dict[str, list[int]] = {}
    for tx in block.transactions:
        sender_balance = balances.get(tx.sender, endowment)
        if sender_balance < tx.amount:
            raise ValueError(
                f"replay overspend by {tx.sender} in block {block.height}"
            )
        balances[tx.sender] = sender_balance - tx.amount
        balances[tx.recipient] = balances.get(tx.recipient, endowment) + tx.amount
        if tx.nonce is not None:
            block_nonces.setdefault(tx.sender, []).append(tx.nonce)
    for sender, nonces in block_nonces.items():
        expected_nonce = next_nonces.get(sender, 0)
        ordered = sorted(nonces)
        if len(set(nonces)) != len(nonces):
            raise ValueError(
                f"sender {sender} uses a duplicated sequenced nonce in "
                f"block {block.height}"
            )
        if ordered != list(range(expected_nonce, expected_nonce + len(ordered))):
            raise ValueError(
                f"sequenced nonces {ordered} for sender {sender} in block "
                f"{block.height} do not continue the stream at "
                f"nonce {expected_nonce}"
            )
        next_nonces[sender] = expected_nonce + len(ordered)
return blocks

